BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats5-q01', '相関と回帰',
   'クラスの身長と体重を1人ずつ点にして散布図を描いたら、きれいな右上がりの帯になった。この「2つの量がどれくらい一直線に近い関係にあるか」を-1から+1の数字で表したものは何？',
   NULL::text,
   '["相関係数", "分散", "標準偏差", "偏差値"]',
   0, '[0]', 'single',
   '{"asked": "2つの量の直線的な関係の強さを、1つの数字にする道具の名前。", "point": "相関係数は必ず-1から+1の間の値になり、+1に近いほど強い右上がり、-1に近いほど強い右下がりの関係。", "kid": "相関係数は、散布図に打った点が「どれくらいきれいな一直線に近い並び方をしているか」を、-1から+1までの1つの数字にしたもの。", "eg": "2人3脚のペアのように、片方が速く走るほどもう片方も速く走るなら「息がぴったり合っている」。相関係数は、この息の合い具合を数字にしたもの。", "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">点の並び方と相関係数の大きさ</text><line x1=\"8\" y1=\"26\" x2=\"8\" y2=\"100\" stroke=\"#2a2f3f\"/><line x1=\"8\" y1=\"100\" x2=\"103\" y2=\"100\" stroke=\"#2a2f3f\"/><circle cx=\"20\" cy=\"94\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"30\" cy=\"88\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"40\" cy=\"78\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"50\" cy=\"72\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"60\" cy=\"64\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"70\" cy=\"55\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"80\" cy=\"48\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"90\" cy=\"38\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"96\" cy=\"32\" r=\"3\" fill=\"#60a5fa\"/><text x=\"55\" y=\"118\" fill=\"#6ab08d\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">r = 0.9</text><line x1=\"124\" y1=\"26\" x2=\"124\" y2=\"100\" stroke=\"#2a2f3f\"/><line x1=\"124\" y1=\"100\" x2=\"219\" y2=\"100\" stroke=\"#2a2f3f\"/><circle cx=\"138\" cy=\"40\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"148\" cy=\"85\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"158\" cy=\"55\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"168\" cy=\"25\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"178\" cy=\"92\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"188\" cy=\"45\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"198\" cy=\"68\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"208\" cy=\"35\" r=\"3\" fill=\"#60a5fa\"/><text x=\"171\" y=\"118\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">r ≈ 0</text><line x1=\"240\" y1=\"26\" x2=\"240\" y2=\"100\" stroke=\"#2a2f3f\"/><line x1=\"240\" y1=\"100\" x2=\"335\" y2=\"100\" stroke=\"#2a2f3f\"/><circle cx=\"252\" cy=\"32\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"262\" cy=\"38\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"272\" cy=\"48\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"282\" cy=\"55\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"292\" cy=\"64\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"302\" cy=\"72\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"312\" cy=\"78\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"322\" cy=\"88\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"328\" cy=\"94\" r=\"3\" fill=\"#60a5fa\"/><text x=\"287\" y=\"118\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">r = -0.9</text></svg>", "terms": [["相関係数", "2つの量の直線的な関係の強さを-1〜+1で表す数"], ["正の相関", "片方が増えるともう片方も増える関係。相関係数はプラス"], ["負の相関", "片方が増えるともう片方は減る関係。相関係数はマイナス"]], "think": "点が右上がりの一直線に近いほど+1に近づき、右下がりの一直線に近いほど-1に近づく。点がバラバラで並び方に規則が見えなければ0に近くなる。だから相関係数を見るだけで、散布図を描かなくても「右上がりか、右下がりか、関係が見えないか」が数字で分かる。", "vs": "相関係数はあくまで「まっすぐな関係」の強さだけを測る数字で、身長そのものの大きさや散らばりの大きさ（分散・標準偏差）とは別物。", "why_asked": "2つの量の関係を毎回散布図で見比べるのは大変。関係の強さを1つの数字に要約できれば、たくさんのペアを一気に比べたり、報告書に数字1つで書いたりできる。だから発明された。", "usecase": "広告費と売上の関係、勉強時間と成績の関係のように、「この2つはどれくらい関係が強いか」を調べる分析のいちばん基本の数字。", "opt": ["正解。相関係数は2つの量の直線的な関係の強さを-1〜+1の数字で表す。", "分散は1つの量のばらつきの大きさを表す数で、2つの量の関係を測るものではない。", "標準偏差は分散の平方根で、これも1つの量のばらつきを表す数。2つの量の関係とは別物。", "偏差値は1つの量について平均からの位置を表す数で、2つの量の関係を表すものではない。"]}'),

  ('stats5-q02', '相関と回帰',
   'ある文房具店で、「広告を出した日数」と「来店客数」の相関係数を計算したら0.85だった。この0.85という数字の強さを表す言い方として一番近いのはどれ？',
   NULL::text,
   '["かなり強い関係がある", "ほとんど関係がない", "多少の関係がある程度", "完全に一致した関係"]',
   0, '[0]', 'single',
   '{"asked": "相関係数の数字の大きさから、関係の強さをどう読むか。", "point": "目安として、絶対値が0.7以上ならかなり強い、0.2前後なら弱い、0や1ぴったりはめったに出ない。", "kid": "相関係数は数字が大きいほど関係が強い。だいたい0.7以上ならかなり強い、0.4前後ならそこそこ、0.2以下ならほとんど関係なし、という感覚のものさしがある。", "eg": "テストの点数のように、100点満点中70点なら「よくできた」、20点なら「あまりできていない」と感じる感覚に近い。相関係数も0.7以上なら「よく揃っている」と読む。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.3\" text-anchor=\"middle\" font-weight=\"600\">相関係数の絶対値が大きいほど関係が強い</text><polygon points=\"297.5,58 291.5,46 303.5,46\" fill=\"#6ab08d\"/><text x=\"297.5\" y=\"36\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">0.85</text><rect x=\"140.0\" y=\"62\" width=\"60.0\" height=\"10\" fill=\"#8892a4\" opacity=\"0.22\"/><rect x=\"275.0\" y=\"62\" width=\"45.0\" height=\"10\" fill=\"#3b82f6\" opacity=\"0.28\"/><rect x=\"20\" y=\"62\" width=\"45.0\" height=\"10\" fill=\"#3b82f6\" opacity=\"0.28\"/><line x1=\"20\" y1=\"72\" x2=\"320\" y2=\"72\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"72\" x2=\"20\" y2=\"80\" stroke=\"#2a2f3f\"/><text x=\"20\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">-1</text><line x1=\"65.0\" y1=\"72\" x2=\"65.0\" y2=\"80\" stroke=\"#2a2f3f\"/><text x=\"65.0\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">-0.7</text><line x1=\"170\" y1=\"72\" x2=\"170\" y2=\"80\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><line x1=\"275.0\" y1=\"72\" x2=\"275.0\" y2=\"80\" stroke=\"#2a2f3f\"/><text x=\"275.0\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0.7</text><line x1=\"320\" y1=\"72\" x2=\"320\" y2=\"80\" stroke=\"#2a2f3f\"/><text x=\"320\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1</text><text x=\"170\" y=\"108\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">弱い</text><text x=\"297.5\" y=\"108\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">強い</text><text x=\"42.5\" y=\"108\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">強い</text><text x=\"170\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">目安：絶対値0.7以上はかなり強い、0.2前後は弱い</text></svg>", "terms": [["相関係数の目安", "絶対値が0.7以上は強い、0.4前後はそこそこ、0.2以下は弱い、というだいたいの感覚"], ["絶対値", "符号（プラスマイナス）を無視した大きさ。-0.85も0.85も強さは同じ"]], "think": "相関係数は-1から+1までしか動かない数字なので、0.85は+1にかなり近い位置にある。目安の境目（0.7）をはっきり超えているので、「かなり強い関係」と言ってよい。ただし1.0ぴったり（点が完全に一直線）は現実のデータではほぼ出ないので、0.85は「かなり強いが完全ではない」という位置づけになる。", "vs": "相関係数の強さは絶対値の大きさで決まり、プラスかマイナスかは「増えるほど増えるか、増えるほど減るか」という向きを表すだけ。0.85も-0.85も強さは同じ。", "why_asked": "「相関係数が出た」だけでは判断できず、その数字が強いのか弱いのかを読む感覚が無いと、報告書の数字を正しく解釈できない。だから目安の感覚を知っておく必要がある。", "usecase": "マーケティングで「広告日数と来客数の相関は0.85で強い」のように、分析結果を人に説明するときの言い回しとして使う。", "opt": ["正解。0.85は目安の0.7を超えており、かなり強い関係があると言ってよい。", "ほとんど関係がないと言えるのは、相関係数の絶対値が0.2前後まで小さいとき。0.85はその逆にあたる。", "多少の関係がある程度と言えるのは、絶対値がだいたい0.4前後のとき。0.85はそれよりずっと大きい。", "完全に一致した関係と言えるのは相関係数がちょうど1（または-1）のときで、0.85はそこまで届いていない。"]}'),

  ('stats5-q03', '相関と回帰',
   'ある工場で「残業時間」と「ミスの件数」を調べたら、相関係数はほぼ0だった。散布図を描くと、残業時間が短すぎても長すぎてもミスが増え、ちょうどよい長さのときだけミスが少ないU字の形をしていた。この結果から正しく言えることはどれ？',
   NULL::text,
   '["直線的な関係が無いだけで、曲線のような関係が隠れていることがある", "相関係数が0なら、2つの量には何の関係も無いと言い切ってよい", "相関係数の計算そのものを間違えている可能性が高い", "データの人数が足りないだけで、増やせば相関係数は上がるはずである"]',
   0, '[0]', 'single',
   '{"asked": "相関係数が0のとき、「関係が無い」と言い切ってよいかどうか。", "point": "相関係数は「まっすぐな関係」しか捉えない道具。U字のような曲線の関係があっても、相関係数はほぼ0のままになる。", "kid": "相関係数は、点が一直線に近いかどうかだけを見ている数字。U字やへの字のように曲がった関係があっても、右肩上がりでも右肩下がりでもなければ、相関係数はほぼ0になってしまう。", "eg": "シーソーの真ん中に立つと、右にも左にも傾かない。でも「真ん中に立っている」というだけで、シーソーの上に人が「いない」わけではない。相関係数0も同じで、「まっすぐな関係が無い」だけで、「何の関係も無い」とは限らない。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10.3\" text-anchor=\"middle\" font-weight=\"600\">残業時間とミスの件数（U字の関係）</text><line x1=\"20\" y1=\"22\" x2=\"20\" y2=\"108\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"108\" x2=\"320\" y2=\"108\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><circle cx=\"30\" cy=\"50\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"60\" cy=\"70\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"90\" cy=\"85\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"120\" cy=\"98\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"150\" cy=\"105\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"180\" cy=\"106\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"210\" cy=\"100\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"240\" cy=\"88\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"270\" cy=\"72\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"300\" cy=\"52\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"30\" y1=\"86\" x2=\"300\" y2=\"80\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"8.7\" text-anchor=\"middle\">残業時間（短い←　→長い）</text><text x=\"170\" y=\"136\" fill=\"#c9a04a\" font-size=\"8.7\" text-anchor=\"middle\">当てはめた直線はほぼ平ら（r≈0）</text><text x=\"8\" y=\"64\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\" transform=\"rotate(-90 8 64)\">ミスの件数</text></svg>", "terms": [["直線的な関係", "片方が増えるともう片方も一定の割合で増える（または減る）関係"], ["非線形の関係", "U字やへの字のように、直線では表せない曲がった関係"]], "think": "相関係数は、点の並びを1本の直線に当てはめたとき、どれくらいその直線に沿っているかを数字にしたもの。U字の関係は、左半分は右下がり、右半分は右上がりで、全体にまっすぐな直線を当てはめると、ちょうど平らな線になり傾きがほぼ0になる。これは相関係数がほぼ0であることの表れで、これは「関係が無い」のではなく「まっすぐな関係ではない」ということ。だから相関係数を見る前に、必ず散布図を描いて形を確かめる必要がある。", "vs": "「相関係数が0」と「関係が無い」は同じではない。相関係数が0でも散布図を見ると、はっきりした形（U字など）が見えることがある。数字だけを見て安心しないことが大切。", "why_asked": "相関係数だけを見て「関係なし」と結論づけると、U字のような実務上重要な関係を見逃してしまう。だから統計では「数字と一緒に図も見る」ことが強く勧められる。", "usecase": "運動と体調の関係（運動不足も過剰運動も体調を崩す）、薬の量と効果の関係（少なすぎても多すぎても良くない）など、ちょうどよさが大事な場面でU字の関係はよく現れる。", "opt": ["正解。相関係数はまっすぐな関係しか見ておらず、U字のような曲線の関係は見逃すことがある。", "相関係数が0でも、散布図を見るとU字のようなはっきりした関係が見つかることがあり、言い切れない。", "U字の形が出るのは計算ミスではなく、まっすぐな関係を測る相関係数の性質としてふつうに起こること。", "人数を増やしても、U字の形自体が変わらなければ、当てはめた直線はやはり平らなままで相関係数は上がらない。"]}'),

  ('stats5-q04', '相関と回帰',
   '9人分のデータでは身長と体重にほとんど関係が見えなかった。そこにもう1人、極端に大きい値を持つ人を追加したら、相関係数が一気に0.8まで上がった。この結果の受け止め方として正しいのはどれ？',
   NULL::text,
   '["その1人の外れ値のせいで強く見えている可能性があるので、外れ値を除いても確かめる", "外れ値も含めて計算した相関係数のほうが、常により正しい結果だと考えてよいはずである", "相関係数が上がったのだから、2つの量の関係は本当にそのぶん強くなったと言える", "外れ値が混ざっている時点で、相関係数という計算自体ができなくなってしまうはずである"]',
   0, '[0]', 'single',
   '{"asked": "たった1人の極端な値が、相関係数を大きく動かしてしまう問題。", "point": "相関係数は全員の値を使って計算するので、1つの外れ値だけで大きく変わることがある。外れ値を除いた場合も必ず確かめる。", "kid": "相関係数は、平均や分散と同じく「全員の値」を使って計算する数字。だから、ほとんどの人には当てはまらない関係でも、極端に離れた1人がいるだけで、まるで強い関係があるように見えてしまうことがある。", "eg": "9人でまっすぐ並んで写真を撮っていたところに、1人だけずっと離れた場所に立つ人が入ると、「みんな斜めに並んでいるように見える写真」になってしまう。実際には9人は真っすぐ並んでいたのに。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"20\" y1=\"14\" x2=\"20\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"112\" x2=\"320\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><circle cx=\"45\" cy=\"85\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"60\" cy=\"70\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"75\" cy=\"90\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"90\" cy=\"65\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"105\" cy=\"95\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"120\" cy=\"72\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"135\" cy=\"88\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"150\" cy=\"68\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"165\" cy=\"92\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"278\" cy=\"24\" r=\"5\" fill=\"#c47070\"/><text x=\"278\" y=\"14\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">1人だけ極端な値</text><line x1=\"30\" y1=\"80\" x2=\"170\" y2=\"78\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"100\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">9人だけならほぼ無相関（実線）</text><line x1=\"30\" y1=\"98\" x2=\"278\" y2=\"25\" stroke=\"#60a5fa\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/><text x=\"230\" y=\"100\" fill=\"#60a5fa\" font-size=\"8.3\" text-anchor=\"middle\">外れ値を入れると強い相関に見える（点線）</text></svg>", "terms": [["外れ値", "仲間から極端に離れた値"], ["見かけの相関", "一部のデータのせいで、実際より強く（または弱く）見えている相関"]], "think": "なぜ1人の値でここまで動くのかがカギ。相関係数は「点がどれくらい一直線に沿っているか」を全員分の位置関係から計算する。9人がバラバラに散らばっていても、遠く離れた1点が加わると、その1点へ向かう方向がとても目立つ直線として浮かび上がり、計算上は「よく揃っている」ことになってしまう。だから相関係数が高く出たときほど、まず散布図を見て、その高さが多数の点によるものか、1点だけによるものかを確かめる必要がある。", "vs": "「相関係数が高い＝関係が強い」と早合点しないこと。外れ値を含めた計算と、外れ値を除いた計算の両方を見比べて、どちらが実態に近いかを判断する。", "why_asked": "現実のデータには入力ミスや特殊な例が混ざりやすい。それに気づかず相関係数だけを信じると、「関係がある」という誤った結論をレポートに書いてしまう。", "usecase": "アンケートや実験データの分析で、相関係数が急に高く（または低く）出たときに、まず外れ値の有無を疑う習慣。データ分析の実務で欠かせない確認作業。", "opt": ["正解。1人の外れ値が相関係数を押し上げている可能性があるので、外れ値を除いた場合も確認するべき。", "外れ値を含めた数字のほうが常に正しいとは言えない。むしろ実態からずれて見えることが多い。", "相関係数が上がったこと自体は事実だが、それが9人本来の関係を表しているとは限らない。", "相関係数は外れ値があっても普通に計算できる。計算できなくなるわけではなく、値がゆがむだけである。"]}'),

  ('stats5-q05', '相関と回帰',
   'ある地域で月ごとの「アイスの売上」と「水難事故の件数」を調べたら、強い正の相関があった。この結果から「アイスを食べると水難事故が増える」と言えるか？',
   NULL::text,
   '["言えない。気温という共通の原因が両方を押し上げている疑似相関の可能性が高い", "言える。アイスを食べて満腹になると泳ぎが下手になり、事故が増えるからである", "言える。水難事故のニュースを見て不安になった人が、アイスを買って気を紛らわすからである", "言えない。そもそもこの2つのデータの相関係数は誤差の範囲でしかなく無視してよい"]',
   0, '[0]', 'single',
   '{"asked": "強い相関があるからといって、片方がもう片方の原因だと言えるかどうか。", "point": "相関があっても因果があるとは限らない。両方を同時に動かす「第3の変数」が隠れていないかを必ず疑う。", "kid": "アイスの売上と水難事故は、たしかに一緒に増えたり減ったりする。でもそれは、アイスが事故を起こしているのではなく、「暑い日」という共通の原因が、アイスの売上も水難事故もどちらも押し上げているだけ。", "eg": "花火大会の日は、屋台の売上も、迷子の届け出件数も、どちらも増える。屋台が迷子を作っているわけではなく、「人が大勢集まる日」という共通の原因が両方を押し上げている。", "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10.3\" text-anchor=\"middle\" font-weight=\"600\">気温という共通の原因が両方を動かす</text><rect x=\"130.0\" y=\"20.0\" width=\"80\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"38\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">気温</text><rect x=\"24.0\" y=\"94.0\" width=\"92\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"70\" y=\"112\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">アイスの売上</text><rect x=\"224.0\" y=\"94.0\" width=\"92\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"270\" y=\"112\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">水難事故</text><line x1=\"150\" y1=\"48\" x2=\"95\" y2=\"94\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"190\" y1=\"48\" x2=\"245\" y2=\"94\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"116\" y1=\"108\" x2=\"224\" y2=\"108\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><text x=\"170\" y=\"132\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">見かけの相関（原因ではない）</text></svg>", "terms": [["疑似相関", "2つの量に直接の関係が無いのに、第3の変数のせいで相関があるように見えること"], ["第3の変数", "結果として現れた2つの量の、本当の共通の原因になっている隠れた要因（ここでは気温）"]], "think": "気温が上がると、暑さをしのぐためにアイスを買う人が増える。同時に、気温が上がると泳ぎに行く人も増え、水の事故に遭う人数も増える。つまり気温が「アイスの売上」と「水難事故」のそれぞれを別々に押し上げているだけで、アイスの売上そのものが事故の原因になっているわけではない。相関係数の計算は「何が原因で何が結果か」までは教えてくれないので、強い相関を見つけたら、必ず「他に両方を動かしている原因は無いか」を考える必要がある。", "vs": "「相関がある」は「一緒に動く」という事実だけを表す。「因果がある」は「片方が原因で、もう片方が結果になる」という一歩踏み込んだ主張。相関だけでは因果までは証明できない。", "why_asked": "相関を因果と勘違いすると、「アイスの販売を規制すれば水難事故が減る」のような的外れな対策につながる。統計を使う人が必ず気をつけるべき、一番有名な落とし穴。", "usecase": "ニュースやSNSで「AとBに相関がある」という報道を見たとき、それが本当に因果関係なのか、それとも第3の変数（季節・年齢・地域など）が隠れていないかを疑う習慣として使う。", "opt": ["正解。気温が両方を押し上げているだけの疑似相関の可能性が高く、アイスが事故の原因とは言えない。", "食べて満腹になるからという説明は、水難事故が起きる時間帯や場所の実態とかみ合わず、こじつけに近い。", "事故のニュースを見て安心のためにアイスを買うという流れは、順番が逆で、実際のデータの動きとも合わない。", "強い正の相関があると述べられており、誤差の範囲で無視できるという前提そのものがこの状況と食い違う。"]}'),

  ('stats5-q06', '相関と回帰',
   '不動産サイトで、部屋の広さ（m²）と家賃のデータを散布図にした。来月契約する25m²の部屋の家賃をこの散布図から予測したい。そのために点の上に引く「予測のための線」を何と呼ぶ？',
   NULL::text,
   '["回帰直線", "相関係数", "分散", "中央値"]',
   0, '[0]', 'single',
   '{"asked": "散布図の上に引いて、値を予測するために使う線の名前。", "point": "点の並びに沿って引き、xの値からyの値を見積もる線が回帰直線。相関係数は関係の強さを表す数字で、線そのものではない。", "kid": "回帰直線は、散布図に散らばった点にできるだけ沿うように引いた1本の直線。この線を使うと、点として実際には無い広さ（たとえば25m²）についても、「だいたいこのくらいの家賃になりそう」という値を線の高さから読み取れる。", "eg": "友達の身長と体重のデータから引いた線があれば、まだ体重を聞いていない新しい友達でも、身長さえ分かれば線の上からだいたいの体重を見積もれる。回帰直線はこの「見積もりの物差し」。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"24\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">回帰直線＝予測のための線</text><line x1=\"44\" y1=\"32\" x2=\"44\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"44\" y1=\"118\" x2=\"316\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><circle cx=\"62\" cy=\"104\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"80\" cy=\"99\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"96\" cy=\"92\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"112\" cy=\"96\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"130\" cy=\"84\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"146\" cy=\"78\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"166\" cy=\"81\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"182\" cy=\"66\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"200\" cy=\"58\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"218\" cy=\"62\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"238\" cy=\"46\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"258\" cy=\"38\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"278\" cy=\"42\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"296\" cy=\"30\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"56\" y1=\"108\" x2=\"304\" y2=\"28\" stroke=\"#3b82f6\" stroke-width=\"2\"/><line x1=\"140\" y1=\"118\" x2=\"140\" y2=\"81\" stroke=\"#6ab08d\" stroke-dasharray=\"4 3\"/><line x1=\"44\" y1=\"81\" x2=\"140\" y2=\"81\" stroke=\"#6ab08d\" stroke-dasharray=\"4 3\"/><circle cx=\"140\" cy=\"81\" r=\"4.5\" fill=\"#6ab08d\"/><text x=\"140\" y=\"133\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">25m²の部屋</text><text x=\"206\" y=\"72\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"start\" font-weight=\"600\">→ 家賃を予測できる</text><text x=\"30\" y=\"75\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\" transform=\"rotate(-90 30 75)\">家賃</text></svg>", "terms": [["回帰直線", "散布図の点にできるだけ沿うように引いた、予測のための直線"], ["説明変数", "予測のもとになる値。ここでは広さ"], ["目的変数", "予測したい値。ここでは家賃"]], "think": "相関係数は「点がどれくらい一直線に近いか」という強さだけを1つの数字で表すもので、線そのものは持っていない。それに対して回帰直線は、実際に散布図の上に引かれる1本の線で、その線の高さを読むことで、データに無い新しいxの値に対してもyの値を見積もれる。「関係の強さを知りたいなら相関係数、実際に予測したいなら回帰直線」と役割が分かれている。", "vs": "相関係数と回帰直線は混同しやすいが役割が違う。相関係数は「強さの数字」、回帰直線は「予測のための線」。強い相関（相関係数が高い）があるほど、回帰直線を使った予測も当てになりやすい。", "why_asked": "散布図を眺めるだけでは、データに無いxの値に対するyの値は分からない。「新しい入力に対して値を見積もりたい」という要求に応えるために回帰直線が生まれた。", "usecase": "不動産の家賃査定、勉強時間からテストの点数の見積もり、広告費から売上の見積もりなど、「xからyを予測したい」場面全般で使う、統計の中でも特によく使われる道具。", "opt": ["正解。散布図の点に沿って引き、新しいxの値からyの値を見積もるための線が回帰直線。", "相関係数は関係の強さを-1〜+1の数字で表すもので、線を引いて予測するための道具ではない。", "分散は1つの量のばらつきの大きさを表す数で、xからyを予測するための線ではない。", "中央値は並べて真ん中の値を表す代表値で、2つの量の関係から予測するための線ではない。"]}'),

  ('stats5-q07', '相関と回帰',
   '回帰直線を引くとき、点と線の「縦のずれ」をもとに、いちばん当てはまりの良い線をどうやって選ぶ？',
   NULL::text,
   '["縦のずれを2乗して全部足した合計が、一番小さくなる線を選ぶ", "縦のずれをそのまま（2乗せず）全部足した合計が、一番小さくなる線を選ぶ", "点と線までの一番近い（斜めの）距離の合計が、一番小さくなる線を選ぶ", "ずれが一番大きい点を無視して、残りの点だけを通るように線を引く"]',
   0, '[0]', 'single',
   '{"asked": "回帰直線を「どういう基準で」引くのか、その決め方。", "point": "各点から線までの縦のずれを2乗して合計し、その合計が一番小さくなる線を選ぶ。これが最小二乗法。", "kid": "回帰直線の引き方には決まったルールがある。それぞれの点から、線まで真上または真下にどれだけ離れているか（縦のずれ）を測り、そのずれを2乗してから全部足す。その合計が一番小さくなるように線を選ぶ、というルール。", "eg": "みんなでロープの高さを決めるとき、頭の上に出てしまう人にも、頭が下にもぐってしまう人にも同じくらい気をつかって、全員のはみ出しの2乗の合計が一番小さくなる高さにロープを張るイメージ。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"9.8\" text-anchor=\"middle\" font-weight=\"600\">縦のずれを2乗して足した合計が最小の線を選ぶ</text><line x1=\"30\" y1=\"100\" x2=\"310\" y2=\"30\" stroke=\"#3b82f6\" stroke-width=\"2\"/><line x1=\"50\" y1=\"95\" x2=\"50\" y2=\"105\" stroke=\"#c47070\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/><circle cx=\"50\" cy=\"105\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"90\" y1=\"85\" x2=\"90\" y2=\"78\" stroke=\"#c47070\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/><circle cx=\"90\" cy=\"78\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"130\" y1=\"75\" x2=\"130\" y2=\"88\" stroke=\"#c47070\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/><circle cx=\"130\" cy=\"88\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"170\" y1=\"65\" x2=\"170\" y2=\"60\" stroke=\"#c47070\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/><circle cx=\"170\" cy=\"60\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"210\" y1=\"55\" x2=\"210\" y2=\"68\" stroke=\"#c47070\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/><circle cx=\"210\" cy=\"68\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"250\" y1=\"45\" x2=\"250\" y2=\"38\" stroke=\"#c47070\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/><circle cx=\"250\" cy=\"38\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"290\" y1=\"35\" x2=\"290\" y2=\"44\" stroke=\"#c47070\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/><circle cx=\"290\" cy=\"44\" r=\"3.5\" fill=\"#60a5fa\"/><text x=\"65\" y=\"122\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">縦のずれ</text><text x=\"170\" y=\"138\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">（最小二乗法）</text></svg>", "terms": [["残差", "点と回帰直線とのあいだの縦のずれ。予測と実際の差"], ["最小二乗法", "残差を2乗して合計した値が一番小さくなるように線を決める方法"]], "think": "なぜ2乗するのかがカギ。ずれをそのまま足すと、線の上に出っぱった点（プラスのずれ）と、線の下にもぐった点（マイナスのずれ）が打ち消し合ってしまい、線をどこに引いてもずれの合計がほぼ0になることがある。これでは「当てはまりが良い線」を選べない。そこでずれを2乗してすべてプラスにしてから合計すると、線から離れた点ほど強く効くようになり、「全体としてどれだけ点から離れているか」を正しく比べられる。だから、この合計が一番小さくなる線を選べば、点全体に一番よく沿った線になる。", "vs": "縦のずれで測るか、斜めの最短距離で測るかは別の流儀。回帰でxからyを予測したいときは、y方向（縦）のずれで測るのが基本のやり方で、斜めの距離を使う方法とは目的も結果も異なる。", "why_asked": "「点にできるだけ沿う線」と言われても、線の引き方は無数にある。誰が引いても同じ線になるよう、はっきりした数式のルールが必要で、それが最小二乗法。回帰分析の土台にある考え方。", "usecase": "表計算ソフトの「近似曲線を追加」機能や、統計ソフトの回帰分析は、裏側でほぼ必ずこの最小二乗法を使って線を決めている。", "opt": ["正解。縦のずれを2乗して合計した値が一番小さくなる線を選ぶ。これが最小二乗法という決め方。", "2乗せずそのまま足すと、線の上下のずれが打ち消し合ってしまい、当てはまりの良い線を選べなくなる。", "点と線の斜めの最短距離を使う方法もあるが、xからyを予測する回帰では縦のずれを使うのが基本になる。", "大きくずれた点を無視すると、その点が持っている情報を捨てることになり、通常の回帰直線の決め方ではない。"]}'),

  ('stats5-q08', '相関と回帰',
   '家賃を広さから予測する回帰分析をしたところ、決定係数はR²=0.64だった。この0.64という数字が表しているのはどれ？',
   NULL::text,
   '["家賃のばらつきのうち64%が、広さという説明変数で説明できるということ", "この回帰直線を使った予測が、64%の確率で当たるということ", "広さと家賃の相関係数がそのまま0.64になっているということ", "実際の家賃と予測した家賃の差（誤差）が、平均して64%もあるということ"]',
   0, '[0]', 'single',
   '{"asked": "決定係数R²という数字が、具体的に何の割合を表しているか。", "point": "決定係数は「目的変数のばらつきのうち、回帰直線で説明できる割合」。0.64なら64%が説明できるという意味。", "kid": "家賃は人によってバラバラ（ばらつきがある）。決定係数は、そのばらつきのうち、どれだけを「広さの違い」で説明できるかをパーセントのような割合で表した数字。", "eg": "クラス全員のテストの点差（ばらつき）のうち、勉強時間の違いでどれだけ説明できるかを考えるようなもの。決定係数が高いほど、「点差のほとんどは勉強時間の違いで説明できる」ということになる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">決定係数R² ＝ 説明できる割合</text><rect x=\"40\" y=\"50\" width=\"166.4\" height=\"34\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"206.4\" y=\"50\" width=\"93.6\" height=\"34\" fill=\"#2a2f3f\"/><rect x=\"40\" y=\"50\" width=\"260\" height=\"34\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"123.2\" y=\"71.0\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">64%</text><text x=\"253.2\" y=\"71.0\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">36%</text><text x=\"123.2\" y=\"100\" fill=\"#60a5fa\" font-size=\"8.7\" text-anchor=\"middle\">広さで説明できる部分</text><text x=\"253.2\" y=\"100\" fill=\"#8892a4\" font-size=\"8.3\" text-anchor=\"middle\">説明できない部分(誤差)</text><text x=\"170\" y=\"118\" fill=\"#e8eaf0\" font-size=\"9.3\" text-anchor=\"middle\">家賃のばらつきのうち64%を広さで説明できる</text></svg>", "terms": [["決定係数(R²)", "目的変数のばらつきのうち、回帰直線で説明できる割合。0〜1の値をとる"], ["残りの部分", "説明変数だけでは説明できない、他の要因や誤差にあたる部分"]], "think": "家賃は広さだけで完全に決まるわけではなく、駅からの距離や築年数など、他の要因や誤差も混ざっている。決定係数は、家賃のばらつき全体を100%としたとき、そのうち何%が「広さの違い」という一本の回帰直線で説明できるかを計算したもの。0.64ということは、家賃のばらつきの64%は広さで説明でき、残り36%は広さ以外の要因や誤差によるということ。1に近いほど、その回帰直線はよく当てはまっていると言える。", "vs": "決定係数R²は、実は相関係数rを2乗した値になっている（r²=R²）。だから相関係数0.64がそのままR²というわけではなく、相関係数の2乗がR²になる、という順番を混同しないこと。", "why_asked": "回帰直線を引いただけでは、その線がどれくらい当てになるのかが分からない。決定係数という「当てはまりの良さ」を数字にする道具が無いと、良い予測モデルと悪い予測モデルを比べられない。", "usecase": "分析レポートで「このモデルのR²は0.64です」のように、予測モデルの性能を報告するときの定番の数字。値が高いほど信頼できる予測とみなされる。", "opt": ["正解。家賃のばらつきのうち64%が広さで説明できるという意味で、残り36%は他の要因や誤差によるもの。", "決定係数は「当たる確率」ではなく「説明できる割合」を表す数字で、的中率のような意味では使わない。", "決定係数は相関係数を2乗した値になるので、相関係数がそのまま0.64というわけではない。", "決定係数は誤差の割合ではなく説明できた割合を表すので、残りの36%が誤差にあたる部分にあたる。"]}'),

  ('stats5-q09', '相関と回帰',
   '家賃を予測するのに「広さ」だけでなく「駅からの距離」も同時に使って予測式を作りたい。このように説明変数を複数同時に使う回帰を何と呼ぶ？',
   NULL::text,
   '["重回帰", "回帰直線", "相関係数", "決定係数"]',
   0, '[0]', 'single',
   '{"asked": "説明変数を1つではなく複数使う回帰の名前。", "point": "説明変数が1つなら単回帰、2つ以上を同時に使うのが重回帰。それぞれの効き具合を同時に計算する。", "kid": "重回帰は、家賃を予測するのに「広さ」と「駅からの距離」のように、複数の説明変数を同時に使う回帰分析。1つの変数だけでは説明しきれない部分を、複数の変数を組み合わせて説明しようとするやり方。", "eg": "料理の味を「塩の量」だけで説明しようとすると無理があるが、「塩の量」と「砂糖の量」と「火加減」を同時に考えれば、もっと味の違いを説明できる。重回帰も同じで、複数の材料（変数）を同時に使う。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.3\" text-anchor=\"middle\" font-weight=\"600\">複数の説明変数を同時に使う＝重回帰</text><rect x=\"25.0\" y=\"29.0\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"80\" y=\"48\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">広さ(m²)</text><rect x=\"25.0\" y=\"93.0\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"80\" y=\"112\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">駅からの距離</text><rect x=\"205.0\" y=\"59.0\" width=\"110\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"260\" y=\"80\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">家賃（予測）</text><line x1=\"135\" y1=\"50\" x2=\"205\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"135\" y1=\"102\" x2=\"205\" y2=\"82\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"138\" fill=\"#8892a4\" font-size=\"8.7\" text-anchor=\"middle\">広さと駅距離、両方の効き具合を同時に計算する</text></svg>", "terms": [["単回帰", "説明変数を1つだけ使う回帰"], ["重回帰", "説明変数を2つ以上同時に使う回帰"], ["係数", "それぞれの説明変数が、目的変数にどれだけ効いているかを表す数字"]], "think": "広さだけで家賃を予測すると、同じ広さでも駅から近いか遠いかで実際の家賃には差が出て、うまく説明できない部分が残る。そこで「駅からの距離」も一緒に式に入れると、広さでは説明できなかった家賃の差の一部を、駅からの距離で説明できるようになる。1つの変数の効き具合（係数）を計算するときも、他の変数の影響を考慮したうえで計算されるので、「広さだけを見たときの効き具合」とは値が変わることがある。", "vs": "「回帰直線」は説明変数が1つ（単回帰）のときの呼び方。散布図に引ける1本の直線だからこの名前がついている。説明変数が2つ以上になると、当てはめる相手はもう平面（さらに増えると超平面）になり、図でいう1本の「直線」ではなくなるので、回帰『式』と呼ぶのが正確。", "why_asked": "現実の家賃は広さだけで決まるわけではない。1つの変数だけでは説明しきれない現象を扱うために、複数の変数を同時に扱える重回帰が必要になった。", "usecase": "家賃査定（広さ・駅距離・築年数）、売上予測（広告費・季節・競合の数）など、実務のほとんどの予測モデルは複数の変数を同時に使う重回帰の形をしている。", "opt": ["正解。広さと駅からの距離のように、説明変数を2つ以上同時に使う回帰を重回帰と呼ぶ。", "回帰直線は説明変数が1つの単回帰で引く1本の線の名前で、複数の変数を同時に使う呼び名ではない。", "相関係数は2つの量の関係の強さを表す数字で、複数の変数を同時に扱う予測式のことではない。", "決定係数は回帰の当てはまりの良さを表す割合で、変数を何個使うかを表す言葉ではない。"]}'),

  ('stats5-q10', '相関と回帰',
   '家賃の重回帰分析に「駅チカかどうか」という情報も加えたい。ただしこれは「はい/いいえ」で答える質的変数。数式に使えるようにするにはどうする？',
   NULL::text,
   '["「駅チカなら1、そうでなければ0」という数字（ダミー変数）に置き換えて回帰式に入れる", "質的変数はどうやっても回帰式には使えないので、この情報はあきらめて外すしかない", "「駅チカ度」を1〜10の主観的な点数に変換してから、そのまま回帰式に入れる", "「駅チカ」「駅チカでない」という文字列のままで、そのまま数式の中に書き入れて計算する"]',
   0, '[0]', 'single',
   '{"asked": "「はい/いいえ」のような質的変数を、回帰分析で使えるようにする方法。", "point": "「あてはまるなら1、あてはまらないなら0」という数字に置き換えるのがダミー変数。これで回帰式に組み込める。", "kid": "回帰の数式は数字同士の計算しかできないので、「駅チカ」「駅チカでない」のような言葉のままでは使えない。そこで「駅チカなら1、駅チカでないなら0」という数字に置き換える。この0/1の数字をダミー変数と呼ぶ。", "eg": "アンケートの回答欄で「はい」にチェックが入っていたら1点、入っていなければ0点として集計するのと同じ発想。言葉のままでは集計できないものを、0と1の数字に置き換えている。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">質的変数を0/1の数字に変える</text><rect x=\"40\" y=\"44\" width=\"140\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"110\" y=\"63\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">駅チカ</text><line x1=\"190\" y1=\"59\" x2=\"230\" y2=\"59\" stroke=\"#60a5fa\"/><rect x=\"240\" y=\"44\" width=\"60\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"270\" y=\"63\" fill=\"#6ab08d\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">1</text><rect x=\"40\" y=\"84\" width=\"140\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"110\" y=\"103\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">駅チカでない</text><line x1=\"190\" y1=\"99\" x2=\"230\" y2=\"99\" stroke=\"#60a5fa\"/><rect x=\"240\" y=\"84\" width=\"60\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"270\" y=\"103\" fill=\"#8892a4\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">0</text><text x=\"170\" y=\"138\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">数字にすれば回帰式にそのまま入れられる</text></svg>", "terms": [["ダミー変数", "質的変数を0と1の数字に置き換えたもの"], ["質的変数", "駅チカかどうかのような、種類を表すラベル"]], "think": "回帰式は「係数×数字」を足し合わせて予測値を作る仕組みなので、文字のままでは掛け算ができない。そこで「駅チカ」という条件に当てはまるかどうかを、当てはまれば1、当てはまらなければ0という数字に置き換える。こうすれば「駅チカである」という情報も、他の数値の説明変数（広さなど）とまったく同じように、係数を掛けて足し合わせる計算に混ぜ込める。0/1というシンプルな数字にすることで、「駅チカだと家賃がどれだけ上がるか」を係数の大きさとして読み取れるようになる。", "vs": "「駅チカ度」のような1〜10の主観点数に変換する方法もあるが、これは順序や間隔の意味が人によってあいまいになりやすい。ダミー変数は「あてはまるか、あてはまらないか」のはっきりした0/1にする点が違う。", "why_asked": "現実のデータには「はい/いいえ」のような質的な情報がたくさん混ざっている。それを回帰の数式に組み込めないと、せっかくの情報を分析に使えず捨てることになる。ダミー変数はその抜け道として生まれた。", "usecase": "「駅チカかどうか」「ペット可かどうか」「男性か女性か」のような質的な条件を回帰式に組み込むとき、実務の重回帰分析でごく普通に使われるテクニック。", "opt": ["正解。あてはまれば1、あてはまらなければ0という数字（ダミー変数）に置き換えれば、回帰式に組み込める。", "質的変数は0/1の数字に置き換えれば回帰式に使えるので、情報をあきらめて外す必要はない。", "1〜10の主観点数は人によって基準がぶれやすく、駅チカかどうかを表す方法としては不向きである。", "文字列のままでは回帰式の掛け算・足し算ができず、数字に置き換えないと計算そのものが成り立たない。"]}'),

  ('stats5-q11', '相関と回帰',
   '家賃の重回帰分析に「広さ（m²）」と「広さ（畳）」という、ほぼ同じ情報を表す2つの変数を両方入れたら、それぞれの係数がプラスとマイナスであべこべの値になり、数字が不安定に暴れた。この現象を何と呼ぶ？',
   NULL::text,
   '["多重共線性という、係数が不安定になる現象", "疑似相関という、隠れた原因が2つを動かす現象", "外れ値という、仲間から極端に離れた値がある状態", "決定係数という、回帰の当てはまりの良さを表す割合"]',
   0, '[0]', 'single',
   '{"asked": "そっくりな説明変数を2つ同時に入れると、係数が暴れてしまう現象の名前。", "point": "そっくりな説明変数を2つ入れると、どちらの効果か切り分けられず係数が不安定になる。これが多重共線性。", "kid": "広さ（m²）と広さ（畳）は、単位が違うだけでほとんど同じ情報。この2つを回帰式に両方入れると、コンピューターは「どちらが本当に家賃を動かしているのか」を区別できなくなり、係数の値がおかしな（あべこべの）値になってしまうことがある。", "eg": "同じ人の体重を「kg」と「g（グラムに直しただけ）」の2つの欄に書いて、両方を使って何かを説明しようとするようなもの。中身は同じ情報なので、2つに分けて考えることに意味が無く、計算が混乱する。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"9.8\" text-anchor=\"middle\" font-weight=\"600\">ほぼ同じ情報の変数を2つ入れると係数が暴れる</text><rect x=\"25.0\" y=\"29.0\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"80\" y=\"48\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">広さ(m²)</text><rect x=\"25.0\" y=\"93.0\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"80\" y=\"112\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">広さ(畳)</text><rect x=\"205.0\" y=\"59.0\" width=\"110\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"260\" y=\"80\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">家賃（予測）</text><line x1=\"135\" y1=\"50\" x2=\"205\" y2=\"70\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><line x1=\"135\" y1=\"102\" x2=\"205\" y2=\"82\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><text x=\"170\" y=\"138\" fill=\"#c9a04a\" font-size=\"8.7\" text-anchor=\"middle\">広さ(m²)と広さ(畳)はほぼ同じ情報</text></svg>", "terms": [["多重共線性", "説明変数どうしがそっくりで、それぞれの効き具合を切り分けられなくなる問題"], ["係数", "各説明変数が目的変数にどれだけ効いているかを表す数字"]], "think": "重回帰の係数は、「他の変数の値を変えないまま、この変数だけを動かしたら目的変数がどれだけ動くか」を表す数字。ところが広さ（m²）と広さ（畳）は常に同じ比率で一緒に動くので、「片方だけを動かす」という状況そのものが存在しない。計算上、どちらの係数が本当の効果を担っているのか決められず、プラスとマイナスに分かれ合ってつじつまを合わせるような、不自然な値になってしまう。これが多重共線性が起きる理由。", "vs": "疑似相関は「2つの結果が、隠れた第3の原因のせいで一緒に動いて見える」話。多重共線性は「説明変数どうしがそっくりすぎて、係数の計算が不安定になる」話で、どちらも変数どうしの関係が絡むが、問題が起きる場所が違う。", "why_asked": "似た変数を両方入れても「情報が増えて予測が良くなる」とは限らず、むしろ係数が信用できなくなる。重回帰を作るときに、説明変数どうしが似すぎていないかを確認する必要があることを知らないと、間違った解釈をしてしまう。", "usecase": "重回帰分析の前に説明変数どうしの相関を確認し、そっくりな変数が無いかをチェックする作業は、多重共線性を避けるために行う。", "opt": ["正解。広さ（m²）と広さ（畳）のようにそっくりな変数を両方入れると、係数の切り分けができず不安定になる現象を指す。", "疑似相関は、隠れた第3の原因が2つの結果を一緒に動かして見える現象で、係数どうしの計算の不安定さの話ではない。", "外れ値は仲間から極端に離れた1つの値のことで、そっくりな変数を2つ入れたことによる係数の不安定さとは別の話。", "決定係数は回帰の当てはまりの良さを表す割合のことで、係数がプラスマイナスであべこべになる現象の名前ではない。"]}'),

  ('stats5-q12', '相関と回帰',
   '健康診断の結果から「病気であるか、ないか」を予測したい。名前に「回帰」と付くのに、実際には0か1かのグループ分け（分類）に使われる手法はどれ？',
   NULL::text,
   '["ロジスティック回帰という、確率をS字で出す分類の手法", "重回帰という、複数の説明変数を同時に使う回帰の手法だ", "回帰直線という、xからyを予測するための線", "決定係数という、回帰の当てはまりの良さを表す割合"]',
   0, '[0]', 'single',
   '{"asked": "「回帰」という名前なのに、実際にはグループ分け（分類）に使われる手法の名前。", "point": "ロジスティック回帰は名前に「回帰」と付くが、出力はS字カーブで0〜1の確率にし、実際には分類に使う手法。", "kid": "ロジスティック回帰は、「病気の確率は何%か」という0〜1のあいだの数字をS字カーブの形で計算し、そのうえで「0.5以上なら病気、未満なら病気でない」のようにグループ分け（分類）する手法。", "eg": "たい焼きという名前でも中に鯛は入っていない。ロジスティック回帰も「回帰」という名前だが、中身は病気か・病気でないかを見分ける分類の道具。名前と中身が一致しない代表例。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10.3\" text-anchor=\"middle\" font-weight=\"600\">確率をS字カーブで0〜1の間に出す</text><line x1=\"20\" y1=\"128\" x2=\"320\" y2=\"128\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"26\" x2=\"20\" y2=\"128\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M30 122 C 90 122, 130 100, 170 77 C 210 54, 250 30, 310 30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><line x1=\"20\" y1=\"77\" x2=\"320\" y2=\"77\" stroke=\"#2a2f3f\" stroke-dasharray=\"4 3\"/><text x=\"14\" y=\"81\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">0.5</text><text x=\"14\" y=\"131\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">0</text><text x=\"14\" y=\"34\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">1</text><circle cx=\"60\" cy=\"120\" r=\"4\" fill=\"#c47070\"/><text x=\"60\" y=\"143\" fill=\"#c47070\" font-size=\"8.3\" text-anchor=\"middle\">低い点数→陰性らしい</text><circle cx=\"280\" cy=\"33\" r=\"4\" fill=\"#6ab08d\"/><text x=\"280\" y=\"143\" fill=\"#6ab08d\" font-size=\"8.3\" text-anchor=\"middle\">高い点数→陽性らしい</text></svg>", "terms": [["分類", "データをいくつかのグループに振り分けること（病気/健康など）"], ["確率", "0〜1の数字で表される、そのグループに入りそうな度合い"]], "think": "ふつうの回帰直線は、点数や広さのようにいくらでも大きくなり得る数を予測する。でも「病気かどうか」は0か1かの2択で、いくらでも大きい数を予測しても意味が無い。そこでロジスティック回帰は、まず回帰と同じように説明変数を足し合わせた数字を作ったあと、その数字をS字の形をした関数に通して、必ず0〜1のあいだの「確率らしい数字」に変換する。0.5を境に、それより高ければ「病気」、低ければ「健康」と分ける。回帰の計算のしくみを土台にしつつ、出てくる答えは確率、その先の使い方は分類、という2段構えになっている。", "vs": "重回帰は、家賃のようにいくらでも大きくなり得る数そのものを予測する。ロジスティック回帰は、0〜1の確率を予測したうえで、最後にグループ分けをする。予測する対象の種類（いくらでも大きい数か、0/1の2択か）がそもそも違う。", "why_asked": "病気の有無、迷惑メールかどうか、契約を続けるかどうかなど、世の中には「0か1か」を予測したい場面がとても多い。ふつうの回帰直線ではうまく扱えないこの需要に応えるために、ロジスティック回帰が生まれた。", "usecase": "健康診断での病気の判定、メールの迷惑メール判定、ローン審査での貸し倒れ予測など、「はい/いいえ」を確率つきで予測したい場面で幅広く使われる。", "opt": ["正解。出力をS字カーブで0〜1の確率にし、そこから分類する。名前は回帰だが中身は分類に使う手法である。", "重回帰は、いくらでも大きくなり得る数そのものを予測する手法で、0/1のグループ分けを目的にはしない。", "回帰直線は予測のための線そのものの呼び名で、確率をS字カーブに変換してグループ分けする手法ではない。", "決定係数は回帰の当てはまりの良さを表す割合の名前で、病気かどうかを見分けるための手法ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
